#!/usr/bin/env node

// src/index.ts
import { execSync, spawn } from "child_process";
import { existsSync, mkdirSync as mkdirSync2 } from "fs";
import { createServer } from "net";
import { stdin as input, stdout as output } from "process";
import { createInterface } from "readline/promises";
import { resolve } from "path";

// src/scaffold.ts
import { mkdirSync, writeFileSync } from "fs";
import { dirname, join } from "path";

// src/templates.ts
var TEMPO_USDC_PARTS = {
  testnetPrefix: "0x20c00000000000000000",
  testnetSuffix: "00000000000000000000",
  mainnetPrefix: "0x20c00000000000000000",
  mainnetSuffix: "0000b9537d11c60e8b50"
};
function tempoCurrencyAddress(testnet) {
  const prefix = testnet ? TEMPO_USDC_PARTS.testnetPrefix : TEMPO_USDC_PARTS.mainnetPrefix;
  const suffix = testnet ? TEMPO_USDC_PARTS.testnetSuffix : TEMPO_USDC_PARTS.mainnetSuffix;
  return String.prototype.concat.call(prefix, suffix);
}
function routeTemplate(vars) {
  const currency = tempoCurrencyAddress(vars.testnet);
  return `import { Mppx, tempo } from 'mppx/server'

const mppx = Mppx.create({
  methods: [
    tempo.charge({
      currency: process.env.TEMPO_CURRENCY as \`0x\${string}\`,
      recipient: process.env.TEMPO_RECIPIENT as \`0x\${string}\`,
      testnet: process.env.TEMPO_TESTNET !== 'false',
    }),
  ],
  secretKey: process.env.MPP_SECRET_KEY!,
})

export async function GET(request: Request) {
  const amount = process.env.PAYMENT_AMOUNT ?? '${vars.price}'
  // mppx compose types are not publicly exported \u2014 cast required
  const result = await (mppx.compose as any)(['tempo/charge', { amount }])(request)
  if (result.status === 402) return result.challenge
  return result.withReceipt(Response.json({ message: 'Access granted', amount }))
}
`;
}
function packageJsonTemplate(vars) {
  return JSON.stringify(
    {
      name: vars.projectName,
      version: "0.1.0",
      private: true,
      scripts: {
        dev: "next dev",
        build: "next build",
        start: "next start",
        _comment_postinstall: "patches mppx Stripe API version string \u2014 remove when mppx ships 2026-03-04.preview",
        postinstall: `node -e "const fs=require('fs');const f='node_modules/mppx/dist/stripe/internal/constants.js';if(fs.existsSync(f))fs.writeFileSync(f,fs.readFileSync(f,'utf8').replace(/'2026-02-25.preview'/,\\"'2026-03-04.preview'\\"))"`
      },
      dependencies: {
        mppx: "^0.6.5",
        next: "16.2.4",
        react: "19.2.4",
        "react-dom": "19.2.4",
        viem: "^2.48.4"
      },
      devDependencies: {
        "@types/node": "^20",
        "@types/react": "^19",
        "@types/react-dom": "^19",
        typescript: "^5"
      }
    },
    null,
    2
  );
}
function tsconfigTemplate() {
  return JSON.stringify(
    {
      compilerOptions: {
        target: "ES2017",
        lib: ["dom", "dom.iterable", "esnext"],
        allowJs: true,
        skipLibCheck: true,
        strict: true,
        noEmit: true,
        esModuleInterop: true,
        module: "esnext",
        moduleResolution: "bundler",
        resolveJsonModule: true,
        isolatedModules: true,
        jsx: "react-jsx",
        incremental: true,
        plugins: [{ name: "next" }],
        paths: { "@/*": ["./src/*"] }
      },
      include: ["next-env.d.ts", "**/*.ts", "**/*.tsx", ".next/types/**/*.ts"],
      exclude: ["node_modules"]
    },
    null,
    2
  );
}
function nextConfigTemplate() {
  return `import type { NextConfig } from 'next'

const nextConfig: NextConfig = {}

export default nextConfig
`;
}
function envTemplate(vars) {
  const currency = tempoCurrencyAddress(vars.testnet);
  return `# Generated by create-mpp-app
TEMPO_RECIPIENT=${vars.address}
TEMPO_RECIPIENT_KEY=${vars.privateKey}
TEMPO_CURRENCY=${currency}
TEMPO_TESTNET=${vars.testnet}
MPP_SECRET_KEY=${vars.secretKey}
PAYMENT_AMOUNT=${vars.price}
`;
}
function gitignoreTemplate() {
  return `# dependencies
/node_modules
/.pnp
.pnp.js

# next.js
/.next/
/out/

# env
.env*
!.env.example

# misc
.DS_Store
`;
}
function envExampleTemplate(vars) {
  const currency = tempoCurrencyAddress(vars.testnet);
  return `TEMPO_RECIPIENT=0x_your_wallet_address
TEMPO_RECIPIENT_KEY=0x_your_private_key
TEMPO_CURRENCY=${currency}
TEMPO_TESTNET=${vars.testnet}
MPP_SECRET_KEY=_your_secret_key
PAYMENT_AMOUNT=${vars.price}
`;
}

// src/scaffold.ts
function scaffold(dir, vars, wallet) {
  const write = (rel, content) => {
    const abs = join(dir, rel);
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, content, "utf8");
  };
  write("package.json", packageJsonTemplate(vars));
  write("tsconfig.json", tsconfigTemplate());
  write("next.config.ts", nextConfigTemplate());
  write(".gitignore", gitignoreTemplate());
  write(".env.local", envTemplate({ ...vars, ...wallet }));
  write(".env.example", envExampleTemplate(vars));
  write("src/app/paid/route.ts", routeTemplate(vars));
  write(
    "src/app/page.tsx",
    `export default function Home() {
  return (
    <main>
      <h1>{process.env.npm_package_name}</h1>
      <p>Paid endpoint: <code>GET /paid</code></p>
    </main>
  )
}
`
  );
}

// src/wallet.ts
import crypto from "crypto";
var DEFAULT_PROVISION_URL = "https://create-mpp-app.vercel.app/api/provision";
async function provisionWallet(projectName) {
  const response = await fetch(resolveProvisionUrl(), {
    method: "POST",
    headers: {
      "content-type": "application/json"
    },
    body: JSON.stringify({
      projectName,
      chainType: "ethereum"
    })
  });
  const payload = await readPayload(response);
  if (!response.ok) {
    throw new Error(readErrorMessage(payload) ?? `Wallet provisioning failed with status ${response.status}.`);
  }
  return {
    address: normalizeAddress(payload),
    privateKey: normalizePrivateKey(payload),
    secretKey: crypto.randomBytes(32).toString("base64")
  };
}
function resolveProvisionUrl() {
  return process.env.CREATE_MPP_APP_PROVISION_URL?.trim() || DEFAULT_PROVISION_URL;
}
async function readPayload(response) {
  const raw = await response.text();
  if (!raw) return void 0;
  try {
    return JSON.parse(raw);
  } catch {
    return raw;
  }
}
function normalizeAddress(payload) {
  const address = readStringField(payload, "address");
  if (!/^0x[a-fA-F0-9]{40}$/.test(address)) {
    throw new Error("Provisioning service returned an invalid wallet address.");
  }
  return address;
}
function normalizePrivateKey(payload) {
  const privateKey = readStringField(payload, "privateKey");
  const normalized = privateKey.startsWith("0x") ? privateKey : `0x${privateKey}`;
  if (!/^0x[a-fA-F0-9]{64}$/.test(normalized)) {
    throw new Error("Provisioning service returned an invalid private key.");
  }
  return normalized;
}
function readStringField(payload, field) {
  if (payload === null || typeof payload !== "object" || Array.isArray(payload)) {
    throw new Error(`Provisioning service returned an invalid response body. Missing ${field}.`);
  }
  const value = payload[field];
  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`Provisioning service returned an invalid ${field}.`);
  }
  return value.trim();
}
function readErrorMessage(payload) {
  if (typeof payload === "string") {
    return payload.trim() || void 0;
  }
  if (payload === null || typeof payload !== "object" || Array.isArray(payload)) {
    return void 0;
  }
  const candidate = payload;
  if (typeof candidate.message === "string" && candidate.message.trim()) {
    return candidate.message.trim();
  }
  if (typeof candidate.error === "string" && candidate.error.trim()) {
    return candidate.error.trim();
  }
  return void 0;
}

// src/index.ts
function parseArgs() {
  const args = process.argv.slice(2);
  const flags = { yes: false, price: "0.01", startDev: true, testnet: true };
  let projectName;
  for (const arg of args) {
    if (arg === "--yes" || arg === "-y") flags.yes = true;
    else if (arg === "--no-dev") flags.startDev = false;
    else if (arg === "--mainnet") flags.testnet = false;
    else if (arg === "--testnet") flags.testnet = true;
    else if (arg.startsWith("--price=")) flags.price = arg.slice("--price=".length);
    else if (!arg.startsWith("-")) projectName = arg;
  }
  return { projectName, flags };
}
async function main() {
  const { projectName: argName, flags } = parseArgs();
  const nonInteractive = flags.yes || !process.stdout.isTTY;
  const project = nonInteractive ? resolveNonInteractiveInputs(argName, flags) : await promptForInputs(argName, flags);
  const dir = resolve(process.cwd(), project.projectName);
  if (existsSync(dir)) {
    console.error(`Error: Directory ${project.projectName} already exists`);
    process.exit(1);
  }
  console.log("Provisioning wallet...");
  const wallet = await provisionWallet(project.projectName);
  console.log(`Wallet: ${wallet.address}`);
  console.log("Scaffolding project...");
  mkdirSync2(dir, { recursive: true });
  scaffold(dir, project, wallet);
  console.log("Installing dependencies...");
  execSync("npm install", { cwd: dir, stdio: "ignore" });
  const devPort = await findAvailablePort();
  if (!flags.startDev) {
    printSuccess(project.projectName, devPort);
    return;
  }
  printAutoStart(project.projectName, devPort);
  await startDevServer(dir, devPort);
}
function resolveNonInteractiveInputs(projectName, flags) {
  if (!projectName) {
    console.error(
      "Error: project name required in non-interactive mode\nUsage: create-mpp-app <name> [--price=0.01] [--testnet|--mainnet] [--yes] [--no-dev]"
    );
    process.exit(1);
  }
  return {
    projectName,
    price: flags.price,
    testnet: flags.testnet
  };
}
async function promptForInputs(projectName, flags) {
  console.log("\ncreate-mpp-app\n");
  const rl = createInterface({ input, output });
  const handleSigint = () => {
    output.write("\nCancelled\n");
    rl.close();
    process.exit(0);
  };
  process.once("SIGINT", handleSigint);
  try {
    const resolvedProjectName = projectName ? projectName : await promptText(
      rl,
      "Project name",
      "my-mpp-api",
      (value) => value ? void 0 : "Project name is required."
    );
    const price = await promptText(
      rl,
      "Price per call (USDC)",
      flags.price,
      (value) => isNaN(Number(value)) || Number(value) <= 0 ? "Price must be a positive number." : void 0
    );
    const testnet = await promptConfirm(rl, "Use testnet (Tempo Moderato)?", flags.testnet);
    return {
      projectName: resolvedProjectName,
      price,
      testnet
    };
  } finally {
    process.off("SIGINT", handleSigint);
    rl.close();
  }
}
async function promptText(rl, label, initialValue, validate) {
  while (true) {
    const answer = (await rl.question(`${label} (${initialValue}): `)).trim();
    const value = answer || initialValue;
    const error = validate(value);
    if (!error) return value;
    console.log(error);
  }
}
async function promptConfirm(rl, label, initialValue) {
  const suffix = initialValue ? "[Y/n]" : "[y/N]";
  while (true) {
    const answer = (await rl.question(`${label} ${suffix}: `)).trim().toLowerCase();
    if (!answer) return initialValue;
    if (answer === "y" || answer === "yes") return true;
    if (answer === "n" || answer === "no") return false;
    console.log("Please enter yes or no.");
  }
}
function printSuccess(name, port) {
  console.log([
    "",
    `Project ready at ./${name}`,
    "",
    "Next steps:",
    `  cd ${name} && npm run dev -- --port ${port}`,
    "",
    "Test payment once it is ready:",
    `  tempo request http://localhost:${port}/paid`,
    "",
    "Wallet address and private key are in .env.local. Back them up."
  ].join("\n"));
}
function printAutoStart(name, port) {
  console.log([
    "",
    `Project ready at ./${name}`,
    "",
    "Starting dev server:",
    `  cd ${name} && npm run dev -- --port ${port}`,
    "",
    "Test payment once it is ready:",
    `  tempo request http://localhost:${port}/paid`,
    "",
    "Wallet address and private key are in .env.local. Back them up."
  ].join("\n"));
}
async function startDevServer(dir, port) {
  const npmCommand = process.platform === "win32" ? "npm.cmd" : "npm";
  await new Promise((resolvePromise, rejectPromise) => {
    const child = spawn(npmCommand, ["run", "dev", "--", "--port", String(port)], {
      cwd: dir,
      stdio: "inherit"
    });
    child.once("error", rejectPromise);
    child.once("exit", (code, signal) => {
      if (code === 0 || signal === "SIGINT" || signal === "SIGTERM") {
        resolvePromise();
        return;
      }
      rejectPromise(new Error(`Dev server exited unexpectedly (${signal ?? `code ${code}`}).`));
    });
  });
}
async function findAvailablePort(startPort = 3e3) {
  for (let port = startPort; port < startPort + 100; port += 1) {
    const available = await canBindPort(port);
    if (available) return port;
  }
  throw new Error(`Could not find an open localhost port starting at ${startPort}.`);
}
async function canBindPort(port) {
  return await new Promise((resolvePromise) => {
    const server = createServer();
    server.once("error", () => {
      resolvePromise(false);
    });
    server.once("listening", () => {
      server.close(() => resolvePromise(true));
    });
    server.listen(port, "127.0.0.1");
  });
}
main().catch((err) => {
  console.error(err instanceof Error ? `Error: ${err.message}` : err);
  process.exit(1);
});
